#!/usr/bin/env node
// generated by beerpowers v{{BEERPOWERS_VERSION}} — не править: обновляет /beerpowers:update
// yandex-tracker-write — адаптер записи в Яндекс Трекер: задача и баг по шаблону, комментарии,
// связи, статусы, вложения. Постановку читает соседний .claude/bin/yandex-tracker. Команды
// и формат черновика — общий контракт адаптера записи (reference/workspace.md плагина),
// здесь — перевод в API и разметку Яндекс Трекера.
//
//   node .claude/bin/yandex-tracker-write.mjs template task|bug          — пустой черновик по шаблону
//   node .claude/bin/yandex-tracker-write.mjs check <черновик.md>        — сверка черновика с шаблоном
//   node .claude/bin/yandex-tracker-write.mjs create <черновик.md>       — завести задачу
//   node .claude/bin/yandex-tracker-write.mjs edit <КОД> <черновик.md>   — заменить название, описание, поля
//   node .claude/bin/yandex-tracker-write.mjs comment <КОД> <файл.md>    — комментарий
//   node .claude/bin/yandex-tracker-write.mjs comments <КОД> [<id>]      — комментарии: id, автор,
//        первая строка; с id — автор и полный текст одного
//   node .claude/bin/yandex-tracker-write.mjs edit-comment <КОД> <id> <файл.md> — заменить текст
//        своего комментария
//   node .claude/bin/yandex-tracker-write.mjs delete-comment <КОД> <id>  — удалить свой комментарий
//   node .claude/bin/yandex-tracker-write.mjs links <КОД>                — связи задачи
//   node .claude/bin/yandex-tracker-write.mjs link <КОД> <вид> <КОД2> [--replace]
//   node .claude/bin/yandex-tracker-write.mjs unlink <КОД> <КОД2>
//   node .claude/bin/yandex-tracker-write.mjs transitions <КОД>          — статус, переходы, резолюции
//   node .claude/bin/yandex-tracker-write.mjs move <КОД> <переход> [--resolution <ключ>]
//        [--field <поле>=<значение>]… [--comment <файл.md>]
//   node .claude/bin/yandex-tracker-write.mjs attach <КОД> <файл>…
//   node .claude/bin/yandex-tracker-write.mjs detach <КОД> <id вложения>
//
// Вид связи — с точки зрения <КОД>: зависит-от, блокирует, связана, подзадача-для, родитель-для.
//
// Черновик — обычный markdown без разметки трекера: «# название», таблица полей
// «| Поле | Значение |», строка «---», дальше описание. Форму печатает template, правила
// заполнения — скил beerpowers:tracker-task. create и edit сначала гоняют check и без чистого
// check ничего не отправляют.
//
// Перевод в разметку Яндекс Трекера — при отправке:
// - картинка «![подпись](путь)» и файл «[имя](путь)» локальным путём от каталога черновика —
//   файл загружается, ссылка становится вложением Трекера (у файла — :file[…]{type=…});
//   вложение оказывается и в списке вложений задачи;
// - подпись — последняя строка «© Клод Клодыч <отчество по модели сессии>» — становится
//   оранжевым курсивом.
// Разметка Трекера, уже стоящая в тексте (описание, взятое из задачи для правки), проходит
// как есть.
//
// Подпись сессии ставит сам скрипт: отчество — по модели, которая ведёт сессию (Opus —
// Опусович, Sonnet — Сонетович, Haiku — Хайкувич, Fable — Фейблович). Модель он берёт из
// транскрипта сессии: Claude Code передаёт команде CLAUDE_CODE_SESSION_ID, транскрипт лежит
// в projects/<каталог проекта>/<id>.jsonl каталога настроек Claude, у последнего ответа
// модели — её имя. Нет подписи в тексте — скрипт её дописывает; есть, но не по модели
// сессии, — отказ. Модель узнать не удалось (скрипт запущен не из Claude Code) — подпись
// пишет сессия, а скрипт сверяет только её форму.
//
// Почему так, а не прямыми вызовами API:
// - У пары задач Трекер держит одну связь: новая связь на ту же пару молча заменяет прежнюю.
//   Поэтому link читает связи пары и без --replace чужой вид не перезаписывает.
// - Ключу задачи из описания Трекер сам ставит связь «связана». Поэтому create и edit, у которых
//   черновик — полное состояние задачи, заменяют её видом из черновика.
// - Каждое вложение поднимает версию задачи, а правка со старой версией получает 409.
//   Поэтому edit перечитывает версию после загрузок, прямо перед правкой.
// - Удалённое вложение оставляет в тексте мёртвую ссылку. Поэтому detach отказывает, пока
//   вложение упомянуто в описании.
// - Последняя строка описания и комментария — подпись сессии; без неё запись не уходит.
// - Права на правку и удаление комментария Трекер даёт по роли в очереди, а не по авторству:
//   токен администратора очереди пропустит и чужой комментарий. Поэтому edit-comment
//   и delete-comment сначала сверяют автора комментария с владельцем токена и чужой не трогают.
//
// Доступы — как у yandex-tracker: переменные окружения YANDEX_TRACKER_TOKEN,
// YANDEX_TRACKER_ORG_ID, YANDEX_TRACKER_ORG_TYPE, затем .claude/yandex-tracker-settings.json,
// затем ~/.claude/yandex-tracker-settings.json. Токену нужен scope tracker:write.
// Токен нигде не печатается.

import crypto from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const self = fileURLToPath(import.meta.url);

if (['-h', '--help', undefined].includes(process.argv[2])) {
  const lines = fs.readFileSync(self, 'utf8').split('\n').slice(2);
  const end = lines.findIndex((l) => !l.startsWith('//'));
  process.stdout.write(lines.slice(0, end).map((l) => l.replace(/^\/\/ ?/, '')).join('\n') + '\n');
  process.exit(0);
}

const API = (process.env.YANDEX_TRACKER_API_HOST || 'https://api.tracker.yandex.net') + '/v2';
const WEB = 'https://tracker.yandex.ru';

function die(msg) {
  process.stderr.write(msg + '\n');
  process.exit(1);
}

// ---------- шаблон ----------

// Порядок секций фиксирован; вторым элементом — обязательность. Тексты правил — в скиле
// beerpowers:tracker-task, здесь только то, что проверяется механически.
const SECTIONS = {
  task: [
    ['Цель', true],
    ['Контекст', false],
    ['Где', false],
    ['Что делаем', true],
    ['Критерии приёмки', true],
    ['Вне объёма', false],
  ],
  bug: [
    ['Где', true],
    [['Шаги воспроизведения', 'Как обнаружено'], true],
    ['Фактический результат', true],
    ['Ожидаемый результат', true],
    ['Доказательства', true],
    ['Влияние', true],
    ['Вне объёма', false],
  ],
};

const TYPES = { 'Задача': 'task', 'Ошибка': 'bug' };
const FIELDS = ['Очередь', 'Тип', 'Доска', 'Теги', 'Исполнитель', 'QA', 'Ревьюер', 'Связи'];
const HEADER_LABELS = ['Зависит от:', 'Блокирует:', '⚠️ При выкладке:'];
// Отчество подписи — по семейству модели сессии.
const PATRONYMIC = { opus: 'Опусович', sonnet: 'Сонетович', haiku: 'Хайкувич', fable: 'Фейблович' };
// Подпись в черновике — простой строкой; оранжевый курсив — уже отправленная, в тексте из задачи.
const SIGN_TEXT = `© Клод Клодыч (?:${Object.values(PATRONYMIC).join('|')})`;
const SIGNATURE = new RegExp(`^(?:${SIGN_TEXT}|\\{orange\\}\\(\\*${SIGN_TEXT}\\*\\))$`);
const SIGN_PLAIN = new RegExp(`^${SIGN_TEXT}$`);
// Последняя строка, которая пытается быть подписью: простая или оранжевая, начинается с «©».
const SIGN_LIKE = /^(?:\{orange\}\(\*)?©/;
const SIGN_ANY = `© Клод Клодыч <${Object.values(PATRONYMIC).join('|')} — по модели сессии>`;

const configDir = process.env.CLAUDE_CONFIG_DIR || path.join(os.homedir(), '.claude');

// Семейство модели сессии по её транскрипту: последний ответ модели называет её имя.
// Не узнать — null, и подпись остаётся на сессии.
function sessionModel() {
  const id = process.env.CLAUDE_CODE_SESSION_ID || '';
  if (!/^[\w-]+$/.test(id)) return null;
  const root = path.join(configDir, 'projects');
  let dirs;
  try { dirs = fs.readdirSync(root); } catch { return null; }
  for (const dir of dirs) {
    const file = path.join(root, dir, `${id}.jsonl`);
    if (!fs.existsSync(file)) continue;
    const lines = fs.readFileSync(file, 'utf8').split('\n');
    for (let i = lines.length - 1; i >= 0; i--) {
      if (!lines[i].includes('"assistant"')) continue;
      let model;
      try { model = JSON.parse(lines[i]).message?.model; } catch { continue; }
      // Служебные записи без модели («<synthetic>») пропускаются.
      const family = Object.keys(PATRONYMIC).find((f) => String(model || '').includes(f));
      if (family) return family;
    }
  }
  return null;
}

const SESSION = sessionModel();
const OWN_SIGN = SESSION ? `© Клод Клодыч ${PATRONYMIC[SESSION]}` : null;
// Ключ задачи, но не имя файла по ключу: SHOP-44-tech.md связи не требует.
const KEY = /\b[A-Z][A-Z0-9]+-\d+\b(?!-[a-zа-яё])/g;

// Вид связи с точки зрения задачи-источника → relationship API и обратно по type/direction.
const KINDS = {
  'зависит-от': 'depends on',
  'блокирует': 'is dependent by',
  'связана': 'relates',
  'подзадача-для': 'is subtask for',
  'родитель-для': 'is parent task for',
};
// Подписи вида в поле «Связи» черновика.
const KIND_WORDS = [
  ['зависит от', 'зависит-от'],
  ['блокирует', 'блокирует'],
  ['связана с', 'связана'],
  ['подзадача для', 'подзадача-для'],
  ['родитель для', 'родитель-для'],
];

function kindOf(link) {
  const t = link.type?.id;
  const d = link.direction;
  if (t === 'relates') return 'связана';
  if (t === 'depends') return d === 'outward' ? 'зависит-от' : 'блокирует';
  if (t === 'subtask') return d === 'inward' ? 'подзадача-для' : 'родитель-для';
  return `${t}/${d}`;
}

function skeleton(type) {
  const head = [
    `# <${type === 'bug' ? 'где: что не так' : 'результат глазами пользователя'} (front|back)>`,
    '',
    '| Поле | Значение |',
    '|---|---|',
    '| Очередь | <ОЧЕРЕДЬ> |',
    `| Тип | ${type === 'bug' ? 'Ошибка' : 'Задача'} |`,
    '| Доска | <id доски> |',
    '| Теги | Frontend |',
    '| Исполнитель | — |',
    '| QA | — |',
    '| Ревьюер | — |',
    '| Связи | — |',
    '',
    '---',
    '',
    '**Зависит от:**',
    '- <КОД — что ждём, или внешнее: что и от кого>',
    '',
  ];
  const body = SECTIONS[type].flatMap(([name, required]) => [
    `## ${Array.isArray(name) ? name[0] : name}`,
    '',
    required ? '<обязательно>' : '<необязательно: нечего писать — секцию убрать>',
    ...(name === 'Где' ? ['- <сайт>: <полный адрес страницы> (сейчас 404 — если страницы ещё нет)'] : []),
    '',
  ]);
  return [...head, ...body, OWN_SIGN || SIGN_ANY, ''].join('\n');
}

// ---------- черновик ----------

function parseDraft(file) {
  if (!fs.existsSync(file)) die(`нет файла черновика: ${file}`);
  const lines = fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n').split('\n');
  const errors = [];
  let i = 0;
  while (i < lines.length && !lines[i].trim()) i++;
  const title = /^# (.+)$/.exec(lines[i] || '');
  if (!title) return { errors: ['первая строка черновика — «# название задачи»'] };
  const summary = title[1].trim();
  i++;
  // Служебная заметка под названием («> черновик…») в Трекер не уходит.
  while (i < lines.length && (!lines[i].trim() || lines[i].startsWith('>'))) i++;
  const fields = {};
  let rows = 0;
  while (i < lines.length && lines[i].startsWith('|')) {
    const cells = lines[i].split('|').slice(1, -1).map((c) => c.trim());
    rows++;
    if (rows > 2 && cells.length >= 2) fields[cells[0]] = cells[1];
    i++;
  }
  if (!rows) errors.push('после названия — таблица полей «| Поле | Значение |»');
  while (i < lines.length && !lines[i].trim()) i++;
  if (lines[i] !== '---') errors.push('таблицу полей и описание разделяет строка «---»');
  const description = lines.slice(i + 1).join('\n').trim();
  return { summary, fields, description, errors, dir: path.dirname(path.resolve(file)) };
}

const none = (v) => !v || v === '—' || v === '-';
const list = (v) => (none(v) ? [] : v.split(/[;,]/).map((x) => x.trim()).filter(Boolean));

function parseLinks(value, errors) {
  const out = [];
  for (const item of none(value) ? [] : value.split(';').map((x) => x.trim()).filter(Boolean)) {
    const hit = KIND_WORDS.find(([w]) => item.toLowerCase().startsWith(w + ' '));
    const key = item.match(KEY);
    if (!hit || !key) {
      errors.push(`связь «${item}»: форма «<вид> <КОД>», вид — ${KIND_WORDS.map(([w]) => w).join(', ')}`);
      continue;
    }
    for (const k of key) out.push({ kind: hit[1], key: k });
  }
  return out;
}

function sectionsOf(description) {
  const lines = description.split('\n');
  const first = lines.findIndex((l) => l.startsWith('## '));
  const header = first < 0 ? lines : lines.slice(0, first);
  const sections = [];
  for (let i = 0; i < lines.length; i++) {
    const m = /^## (.+)$/.exec(lines[i]);
    if (m) sections.push({ name: m[1].trim(), body: [] });
    else if (sections.length) sections[sections.length - 1].body.push(lines[i]);
  }
  return { header, sections };
}

// Список пунктов шапки: «**Зависит от:**» и строки «- …» под ним.
function headerLists(header) {
  const out = {};
  let cur = null;
  const errors = [];
  for (const l of header) {
    if (!l.trim()) continue;
    const label = /^\*\*(.+?)\*\*\s*$/.exec(l.trim());
    if (label && HEADER_LABELS.includes(label[1])) { cur = label[1]; out[cur] = []; continue; }
    if (cur && /^\s*- /.test(l)) { out[cur].push(l.replace(/^\s*- /, '').trim()); continue; }
    errors.push(`до первой секции — только шапка (${HEADER_LABELS.map((x) => `**${x}**`).join(', ')}), лишнее: «${l.trim().slice(0, 60)}»`);
  }
  for (const [k, v] of Object.entries(out)) if (!v.length) errors.push(`**${k}** без пунктов — строку убрать`);
  return { lists: out, errors };
}

// Локальная ссылка — не адрес в сети, не якорь и не вложение, уже загруженное в Трекер.
const isLocal = (target) => !/^([a-z][a-z0-9+.-]*:|\/|#)/i.test(target);

function localRefs(text) {
  const refs = [];
  const img = /!\[([^\]]*)\]\(([^)\s]+)\)/g;
  // Ссылка на файл — обычная markdown-ссылка, но не картинка и не :file[…] Трекера.
  const file = /(?<![!\w])\[([^\]]+)\]\(([^)\s]+)\)/g;
  for (const m of text.matchAll(img)) if (isLocal(m[2])) refs.push({ kind: 'img', all: m[0], name: m[1], target: m[2] });
  for (const m of text.matchAll(file)) if (isLocal(m[2])) refs.push({ kind: 'file', all: m[0], name: m[1], target: m[2] });
  return refs;
}

// Простая подпись последней строкой — оранжевым курсивом Трекера.
function renderSignature(text) {
  const lines = text.trim().split('\n');
  const last = lines[lines.length - 1].trim();
  if (SIGN_PLAIN.test(last)) lines[lines.length - 1] = `{orange}(*${last}*)`;
  return lines.join('\n');
}

// Подпись последней строкой: нет — дописывается подпись модели сессии, есть — сверяется с ней.
// Возвращает текст с подписью.
function signText(text, errors) {
  const trimmed = text.trim();
  const last = trimmed.split('\n').pop().trim();
  if (SIGN_LIKE.test(last)) {
    if (!SIGNATURE.test(last)) errors.push(`последняя строка «${last}» — не подпись: подпись — «${OWN_SIGN || SIGN_ANY}»`);
    else if (OWN_SIGN && !last.includes(OWN_SIGN)) errors.push(`подпись «${last}» не по модели сессии (${SESSION}): последней строкой — «${OWN_SIGN}» или ничего, скрипт допишет сам`);
    return trimmed;
  }
  if (!OWN_SIGN) {
    errors.push(`последняя строка — подпись «${SIGN_ANY}»: модель сессии скрипту не узнать, подпись пишет сессия`);
    return trimmed;
  }
  return `${trimmed}\n\n${OWN_SIGN}`;
}

function checkText(text, dir, errors, warnings) {
  text = signText(text, errors);
  for (const m of text.matchAll(/<[а-яё][^<>\n]*>/gi)) errors.push(`незаполненное место шаблона: ${m[0]}`);
  for (const r of localRefs(text)) if (!fs.existsSync(path.resolve(dir, r.target))) errors.push(`нет файла для ${r.all}`);
  if (/\.(php|tsx?|jsx?|vue|py|go|java|rb|cs|kt|swift)(:\d+)\b/.test(text)) warnings.push('путь к коду с номером строки — номера устаревают, место в коде — во вложении <КОД>-tech.md по имени модуля или функции');
  if (/(^|[\s(])![0-9]+\b/.test(text)) warnings.push('номер MR в тексте — описание для людей, MR видно в Трекере');
  if (/\b(?=[0-9a-f]*[a-f])(?=[0-9a-f]*[0-9])[0-9a-f]{7,40}\b/.test(text)) warnings.push('похоже на SHA коммита — описание для людей, SHA не нужен');
  if (/₽|\bруб\.|ставк[аи]\s+\d/i.test(text)) errors.push('деньги в тексте: оценок, бюджета и ставок в задаче нет — оценка комментарием');
  return text;
}

function checkDraft(d) {
  const errors = [...d.errors];
  const warnings = [];
  if (errors.length) return { errors, warnings };
  const f = d.fields;
  for (const k of Object.keys(f)) if (!FIELDS.includes(k)) errors.push(`поля «${k}» в шаблоне нет: ${FIELDS.join(', ')}`);
  const type = TYPES[f['Тип']];
  if (!type) errors.push(`поле «Тип»: ${Object.keys(TYPES).join(' или ')}`);
  if (!/^[A-Z][A-Z0-9]+$/.test(f['Очередь'] || '')) errors.push('поле «Очередь»: ключ очереди латиницей, например SHOP');
  if (!/^\d+$/.test(f['Доска'] || '')) errors.push('поле «Доска»: числовой id доски');
  const tags = list(f['Теги']);
  const front = tags.includes('Frontend');
  const back = tags.includes('Backend');
  if (front && back) errors.push('теги Frontend и Backend сразу — это две задачи, по одной на сторону, со связью «зависит от»');
  if (front && !/\(front\)$/.test(d.summary)) errors.push('тег Frontend — название кончается на «(front)»');
  if (back && !/\(back\)$/.test(d.summary)) errors.push('тег Backend — название кончается на «(back)»');
  if (!front && !back) warnings.push('нет тега Frontend или Backend — верно только для задачи не по разработке');
  const links = parseLinks(f['Связи'], errors);
  if (!type) return { errors, warnings };

  const { header, sections } = sectionsOf(d.description);
  const h = headerLists(header);
  errors.push(...h.errors);
  const want = SECTIONS[type];
  let at = 0;
  for (const s of sections) {
    const idx = want.findIndex(([n]) => (Array.isArray(n) ? n.includes(s.name) : n === s.name));
    if (idx < 0) { errors.push(`секции «${s.name}» в шаблоне ${type === 'bug' ? 'бага' : 'задачи'} нет`); continue; }
    if (idx < at) errors.push(`секция «${s.name}» не на своём месте: порядок — ${want.map(([n]) => (Array.isArray(n) ? n[0] : n)).join(' → ')}`);
    at = Math.max(at, idx);
    if (!s.body.join('').trim()) errors.push(`секция «${s.name}» пустая — необязательную убрать, обязательную заполнить`);
    else if (s.name === 'Где' && !hasPage(s.body.join('\n'))) errors.push('## Где: нет адреса страницы, только корень сайта или ничего — укажи полный адрес каждой страницы, которую задача создаёт или меняет (новая страница — адресом, по которому появится, даже если сейчас 404)');
  }
  for (const [n, required] of want) {
    const names = Array.isArray(n) ? n : [n];
    if (required && !sections.some((s) => names.includes(s.name))) errors.push(`нет обязательной секции «${names.join('» или «')}»`);
  }
  if (sections.filter((s) => s.name === 'Шаги воспроизведения' || s.name === 'Как обнаружено').length > 1) errors.push('«Шаги воспроизведения» и «Как обнаружено» — одна из двух');

  // Зависимость из шапки — связью нужного вида; ключ из текста — хоть какой-то связью.
  const has = (kind, key) => links.some((l) => l.kind === kind && l.key === key);
  for (const [label, kind] of [['Зависит от:', 'зависит-от'], ['Блокирует:', 'блокирует']]) {
    for (const item of h.lists[label] || []) {
      for (const key of item.match(KEY) || []) {
        if (!has(kind, key)) errors.push(`«${label.slice(0, -1)}» ${key} — в поле «Связи» нужно «${KIND_WORDS.find(([, k]) => k === kind)[0]} ${key}»`);
      }
    }
  }
  const mentioned = new Set([...(d.description.match(KEY) || [])]);
  for (const key of mentioned) if (!links.some((l) => l.key === key)) warnings.push(`${key} упомянута в тексте, связи с ней нет`);

  const description = checkText(d.description, d.dir, errors, warnings);
  return { errors, warnings, type, links, description };
}

// В «## Где» есть адрес страницы: ссылка с путём длиннее «/». Корень сайта страницей
// не считается, макет Figma — тоже.
function hasPage(text) {
  for (const m of text.matchAll(/https?:\/\/[^\s)<>\]]+/g)) {
    let u;
    try { u = new URL(m[0]); } catch { continue; }
    if (/(^|\.)figma\.com$/.test(u.hostname)) continue;
    if (u.pathname.replace(/\/+$/, '')) return true;
  }
  return false;
}

function report({ errors, warnings }) {
  for (const w of warnings) process.stderr.write(`предупреждение: ${w}\n`);
  for (const e of errors) process.stderr.write(`ошибка: ${e}\n`);
}

// ---------- доступ к API ----------

function setting(file, key) {
  try { const v = JSON.parse(fs.readFileSync(file, 'utf8'))[key]; return typeof v === 'string' ? v : ''; } catch { return ''; }
}

const projectSettings = path.join(path.dirname(path.dirname(self)), 'yandex-tracker-settings.json');
const globalSettings = path.join(configDir, 'yandex-tracker-settings.json');
const cred = { token: process.env.YANDEX_TRACKER_TOKEN || '', orgId: process.env.YANDEX_TRACKER_ORG_ID || '', orgType: process.env.YANDEX_TRACKER_ORG_TYPE || '' };
for (const file of [projectSettings, globalSettings]) {
  cred.token ||= setting(file, 'token');
  cred.orgId ||= setting(file, 'orgId');
  cred.orgType ||= setting(file, 'orgType');
}

let orgHeader = null;

async function raw(method, url, body, header) {
  const opt = { method, headers: { Authorization: `OAuth ${cred.token}`, [header]: cred.orgId } };
  if (body instanceof FormData) opt.body = body;
  else if (body !== undefined) { opt.headers['Content-Type'] = 'application/json'; opt.body = JSON.stringify(body); }
  let r;
  try { r = await fetch(API + url, opt); } catch (e) { die(`не дойти до ${API}: ${e.cause?.code || e.message}`); }
  const text = await r.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = null; }
  return { status: r.status, json, text };
}

async function api(method, url, body) {
  if (!cred.token) die(`нет YANDEX_TRACKER_TOKEN: задай переменную окружения либо заполни ${globalSettings} или ${projectSettings}`);
  if (!cred.orgId) die(`нет YANDEX_TRACKER_ORG_ID: задай переменную окружения либо заполни ${globalSettings} или ${projectSettings}`);
  if (!orgHeader) {
    if (cred.orgType) orgHeader = cred.orgType === 'yandex360' ? 'X-Org-ID' : 'X-Cloud-Org-ID';
    else {
      const probe = await raw('GET', '/myself', undefined, 'X-Cloud-Org-ID');
      orgHeader = probe.status === 401 || probe.status === 403 ? 'X-Org-ID' : 'X-Cloud-Org-ID';
      if (orgHeader === 'X-Org-ID') process.stderr.write('подошёл заголовок X-Org-ID — впиши "orgType": "yandex360" в настройки\n');
    }
  }
  // Шлюз Трекера временами отвечает 502–504. Повторяются только чтение и загрузка файла:
  // повтор создания или комментария после ответа, который не дошёл, завёл бы дубль.
  const retry = method === 'GET' || url.endsWith('/attachments');
  let r;
  for (let attempt = 0; ; attempt++) {
    r = await raw(method, url, body, orgHeader);
    if (!retry || attempt >= 2 || ![502, 503, 504].includes(r.status)) break;
    process.stderr.write(`${r.status} от Трекера, повтор через ${attempt + 1} с\n`);
    await new Promise((ok) => setTimeout(ok, 1000 * (attempt + 1)));
  }
  if (r.status >= 200 && r.status < 300) return r.json;
  const msg = [...(r.json?.errorMessages || []), ...Object.values(r.json?.errors || {})].join('; ') || r.text.slice(0, 300);
  if (r.status === 409 && url === '/issues') die(`409: задача по этому черновику уже заведена (поле unique) — найди её в очереди, повторно не создавай: ${msg}`);
  if (r.status === 403 && /tracker:write/.test(msg)) die('403: токену нужен scope tracker:write — добавь «Запись в трекер» в OAuth-приложении на oauth.yandex.ru и выпусти новый токен');
  if (r.status === 401) die('401: токен не принят — проверь YANDEX_TRACKER_TOKEN');
  die(`${r.status} ${method} ${url.split('?')[0]}: ${msg}`);
}

const MIME = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif', webp: 'image/webp', svg: 'image/svg+xml', md: 'text/markdown', txt: 'text/plain', html: 'text/html', pdf: 'application/pdf', json: 'application/json', csv: 'text/csv', zip: 'application/zip', mov: 'video/quicktime', mp4: 'video/mp4', xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' };
const mimeOf = (file) => MIME[path.extname(file).slice(1).toLowerCase()] || 'application/octet-stream';

function formOf(file) {
  const f = new FormData();
  f.append('file', new Blob([fs.readFileSync(file)], { type: mimeOf(file) }), path.basename(file));
  return f;
}

// Черновик → разметка Трекера: локальные ссылки — загруженными вложениями, подпись — цветом.
// issue задан — файл кладётся прямо в задачу, иначе временной загрузкой, которую привяжет
// создание задачи или комментария.
async function upload(text, dir, issue) {
  const ids = [];
  const done = new Map();
  for (const r of localRefs(text)) {
    const file = path.resolve(dir, r.target);
    let id = done.get(file);
    if (!id) {
      const a = await api('POST', issue ? `/issues/${issue}/attachments` : '/attachments', formOf(file));
      id = a.id;
      done.set(file, id);
      ids.push(id);
      process.stderr.write(`загружено: ${path.basename(file)} → вложение ${id}\n`);
    }
    const url = `/ajax/v2/attachments/${id}?inline=true`;
    const repl = r.kind === 'img'
      ? `![${r.name}](${url})`
      : `:file[${r.name}](${url}){type="${mimeOf(file)}"}`;
    text = text.split(r.all).join(repl);
  }
  return { text: renderSignature(text), ids };
}

function fieldsBody(d) {
  const f = d.fields;
  const body = { summary: d.summary, boards: [{ id: Number(f['Доска']) }], tags: list(f['Теги']) };
  if (!none(f['Исполнитель'])) body.assignee = f['Исполнитель'];
  if (!none(f['QA'])) body.qaEngineer = f['QA'];
  if (!none(f['Ревьюер'])) body.reviewer = f['Ревьюер'];
  return body;
}

async function linksOf(key) {
  return (await api('GET', `/issues/${key}/links`)) || [];
}

// Связь с проверкой пары: та же — ничего не делаем, другая — только с replace.
async function addLink(key, kind, other, replace) {
  if (!KINDS[kind]) die(`вид связи: ${Object.keys(KINDS).join(', ')}`);
  const existing = (await linksOf(key)).find((l) => l.object?.key === other);
  if (existing) {
    const was = kindOf(existing);
    if (was === kind) { process.stderr.write(`связь уже есть: ${key} ${kind} ${other}\n`); return false; }
    if (!replace) die(`у ${key} и ${other} уже есть связь «${was}»: у пары задач Трекер держит одну связь, новая заменит прежнюю — повтори с --replace, если так и нужно`);
  }
  await api('POST', `/issues/${key}/links`, { relationship: KINDS[kind], issue: other });
  process.stderr.write(`связь: ${key} ${kind} ${other}${existing ? ` (была «${kindOf(existing)}»)` : ''}\n`);
  return true;
}

// Владелец токена: Трекер называет пользователя разными id, и автор комментария может прийти
// любым из них.
let owner = null;
async function myself() {
  if (!owner) {
    const u = await api('GET', '/myself');
    const ids = ['uid', 'trackerUid', 'passportUid', 'cloudUid', 'login'].map((k) => u[k]).filter(Boolean).map(String);
    owner = { ids: new Set(ids), display: u.display || u.login };
  }
  return owner;
}

const authorOf = (c) => c.createdBy?.display || c.createdBy?.id || '—';
const isMine = (c, who) => who.ids.has(String(c.createdBy?.id ?? ''));

// Комментарии страницами: следующая страница — от id последнего комментария предыдущей.
async function commentsOf(key) {
  const out = [];
  let after = '';
  for (;;) {
    const page = (await api('GET', `/issues/${key}/comments?perPage=50${after ? `&id=${after}` : ''}`)) || [];
    const fresh = page.filter((c) => !out.some((o) => o.id === c.id));
    out.push(...fresh);
    if (page.length < 50 || !fresh.length) return out;
    after = page[page.length - 1].id;
  }
}

// Комментарий задачи, только свой: чужой правкой и удалением не трогается.
async function ownComment(key, id) {
  const c = await api('GET', `/issues/${key}/comments/${id}`);
  const who = await myself();
  if (!isMine(c, who)) die(`комментарий ${id} в ${key} написал ${authorOf(c)}, а токен — ${who.display}: чужой комментарий скрипт не правит и не удаляет`);
  return c;
}

function readText(file) {
  if (!fs.existsSync(file)) die(`нет файла: ${file}`);
  return fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n').trim();
}

// ---------- команды ----------

const [cmd, ...args] = process.argv.slice(2);
const flag = (name) => { const i = args.indexOf(name); return i < 0 ? null : args.splice(i, 2)[1] ?? die(`${name} без значения`); };
const switchOn = (name) => { const i = args.indexOf(name); if (i < 0) return false; args.splice(i, 1); return true; };
const need = (n, usage) => { if (args.length < n) die(`использование: ${usage}`); };

switch (cmd) {
  case 'template': {
    need(1, 'template task|bug');
    if (!SECTIONS[args[0]]) die('template task или template bug');
    process.stdout.write(skeleton(args[0]));
    break;
  }
  case 'check': {
    need(1, 'check <черновик.md>');
    const res = checkDraft(parseDraft(args[0]));
    report(res);
    if (res.errors.length) process.exit(1);
    process.stdout.write('черновик сходится с шаблоном\n');
    break;
  }
  case 'create': {
    need(1, 'create <черновик.md>');
    const d = parseDraft(args[0]);
    const res = checkDraft(d);
    report(res);
    if (res.errors.length) die('черновик не сходится с шаблоном — ничего не отправлено');
    const { text, ids } = await upload(res.description, d.dir, null);
    // unique — защита от дубля: повторный create того же черновика Трекер отклонит 409.
    const unique = crypto.createHash('sha1').update([d.fields['Очередь'], d.summary, res.description].join('\n')).digest('hex');
    const issue = await api('POST', '/issues', { queue: d.fields['Очередь'], type: res.type, markupType: 'md', description: text, unique, ...fieldsBody(d), ...(ids.length ? { attachmentIds: ids } : {}) });
    // Черновик — полное состояние задачи: его вид связи заменяет «связана», которую Трекер
    // сам ставит каждому ключу из описания.
    for (const l of res.links) await addLink(issue.key, l.kind, l.key, true);
    process.stdout.write(`создана: ${issue.key} ${WEB}/${issue.key}\n`);
    break;
  }
  case 'edit': {
    need(2, 'edit <КОД> <черновик.md>');
    const [key, file] = args;
    const d = parseDraft(file);
    const res = checkDraft(d);
    report(res);
    if (res.errors.length) die('черновик не сходится с шаблоном — ничего не отправлено');
    const { text } = await upload(res.description, d.dir, key);
    const fresh = await api('GET', `/issues/${key}`);
    const body = { ...fieldsBody(d), description: text, markupType: 'md' };
    // Тег пишется заменой, а не добавлением: черновик — полное состояние задачи.
    await api('PATCH', `/issues/${key}?version=${fresh.version}`, body);
    for (const l of res.links) await addLink(key, l.kind, l.key, true);
    process.stdout.write(`изменена: ${key} ${WEB}/${key}\n`);
    break;
  }
  case 'comment': {
    need(2, 'comment <КОД> <файл.md>');
    const [key, file] = args;
    const errors = [];
    const warnings = [];
    const dir = path.dirname(path.resolve(file));
    const body = checkText(readText(file), dir, errors, warnings);
    report({ errors, warnings });
    if (errors.length) die('комментарий не отправлен');
    const { text, ids } = await upload(body, dir, null);
    const c = await api('POST', `/issues/${key}/comments`, { text, markupType: 'md', ...(ids.length ? { attachmentIds: ids } : {}) });
    process.stdout.write(`комментарий ${c.id}: ${WEB}/${key}\n`);
    break;
  }
  case 'comments': {
    need(1, 'comments <КОД> [<id комментария>]');
    const [key, id] = args;
    if (id) {
      const c = await api('GET', `/issues/${key}/comments/${id}`);
      process.stdout.write(`комментарий ${c.id}, автор ${authorOf(c)}, ${c.createdAt || ''}\n\n${c.text || ''}\n`);
      break;
    }
    const who = await myself();
    for (const c of await commentsOf(key)) {
      const first = (c.text || '').trim().split('\n')[0].slice(0, 80);
      process.stdout.write(`${c.id}  ${authorOf(c)}${isMine(c, who) ? ' (свой)' : ''}  ${first}\n`);
    }
    break;
  }
  case 'edit-comment': {
    need(3, 'edit-comment <КОД> <id комментария> <файл.md>');
    const [key, id, file] = args;
    const errors = [];
    const warnings = [];
    const dir = path.dirname(path.resolve(file));
    const body = checkText(readText(file), dir, errors, warnings);
    report({ errors, warnings });
    if (errors.length) die('комментарий не изменён');
    await ownComment(key, id);
    // Файл кладётся прямо в задачу: временную загрузку привязывает только создание комментария.
    const { text } = await upload(body, dir, key);
    await api('PATCH', `/issues/${key}/comments/${id}`, { text, markupType: 'md' });
    process.stdout.write(`комментарий ${id} изменён: ${WEB}/${key}\n`);
    break;
  }
  case 'delete-comment': {
    need(2, 'delete-comment <КОД> <id комментария>');
    const [key, id] = args;
    const c = await ownComment(key, id);
    await api('DELETE', `/issues/${key}/comments/${id}`);
    process.stdout.write(`комментарий ${id} удалён из ${key}\n`);
    const att = [...new Set([...(c.text || '').matchAll(/\/attachments\/(\d+)/g)].map((m) => m[1]))];
    if (att.length) process.stderr.write(`вложения из него остались в задаче: ${att.join(', ')} — убрать: detach\n`);
    break;
  }
  case 'links': {
    need(1, 'links <КОД>');
    for (const l of await linksOf(args[0])) process.stdout.write(`${kindOf(l)} ${l.object?.key} — ${l.object?.display || ''}\n`);
    break;
  }
  case 'link': {
    const replace = switchOn('--replace');
    need(3, 'link <КОД> <вид> <КОД2> [--replace]');
    await addLink(args[0], args[1], args[2], replace);
    break;
  }
  case 'unlink': {
    need(2, 'unlink <КОД> <КОД2>');
    const l = (await linksOf(args[0])).find((x) => x.object?.key === args[1]);
    if (!l) die(`связи ${args[0]} — ${args[1]} нет`);
    await api('DELETE', `/issues/${args[0]}/links/${l.id}`);
    process.stdout.write(`связь удалена: ${args[0]} ${kindOf(l)} ${args[1]}\n`);
    break;
  }
  case 'transitions': {
    need(1, 'transitions <КОД>');
    const issue = await api('GET', `/issues/${args[0]}`);
    const tr = await api('GET', `/issues/${args[0]}/transitions`);
    const q = await api('GET', `/queues/${issue.queue.key}?expand=issueTypesConfig`);
    const cfg = (q.issueTypesConfig || []).find((c) => c.issueType?.key === issue.type?.key);
    process.stdout.write(`статус: ${issue.status.display} (${issue.status.key})\n`);
    process.stdout.write('переходы:\n' + tr.map((t) => `  ${t.id} → ${t.to?.display}`).join('\n') + '\n');
    process.stdout.write(`резолюции для типа «${issue.type?.display}»: ${(cfg?.resolutions || []).map((r) => r.key).join(', ') || '—'}\n`);
    process.stdout.write('обязательные поля перехода Трекер называет только отказом 422 — их значения спрашиваются у человека\n');
    break;
  }
  case 'move': {
    const resolution = flag('--resolution');
    const commentFile = flag('--comment');
    const extra = {};
    for (let f; (f = flag('--field'));) {
      const eq = f.indexOf('=');
      if (eq < 1) die(`--field <поле>=<значение>, получено: ${f}`);
      extra[f.slice(0, eq)] = f.slice(eq + 1);
    }
    need(2, 'move <КОД> <переход> [--resolution <ключ>] [--field <поле>=<значение>]… [--comment <файл.md>]');
    const body = { ...extra };
    if (resolution) body.resolution = resolution;
    if (commentFile) {
      const errors = [];
      const text = signText(readText(commentFile), errors);
      report({ errors, warnings: [] });
      if (errors.length) die('переход не выполнен');
      body.comment = renderSignature(text);
    }
    await api('POST', `/issues/${args[0]}/transitions/${args[1]}/_execute`, body);
    const issue = await api('GET', `/issues/${args[0]}`);
    process.stdout.write(`статус ${args[0]}: ${issue.status.display}${issue.resolution ? `, резолюция «${issue.resolution.display}»` : ''}\n`);
    break;
  }
  case 'attach': {
    need(2, 'attach <КОД> <файл>…');
    const [key, ...files] = args;
    for (const file of files) {
      if (!fs.existsSync(file)) die(`нет файла: ${file}`);
      const a = await api('POST', `/issues/${key}/attachments`, formOf(file));
      process.stdout.write(`вложение ${a.id}: ${a.name} — в тексте :file[${a.name}](/ajax/v2/attachments/${a.id}?inline=true){type="${mimeOf(file)}"}\n`);
    }
    break;
  }
  case 'detach': {
    need(2, 'detach <КОД> <id вложения>');
    const [key, id] = args;
    const issue = await api('GET', `/issues/${key}`);
    if ((issue.description || '').includes(`/attachments/${id}`)) die(`вложение ${id} упомянуто в описании ${key}: сначала убери ссылку правкой описания (edit), иначе в тексте останется мёртвая ссылка`);
    const comments = (await api('GET', `/issues/${key}/comments`)) || [];
    const inComment = comments.filter((c) => (c.text || '').includes(`/attachments/${id}`)).map((c) => c.id);
    await api('DELETE', `/issues/${key}/attachments/${id}`);
    process.stdout.write(`вложение ${id} удалено из ${key}\n`);
    if (inComment.length) process.stderr.write(`ссылка на него осталась в комментариях: ${inComment.join(', ')}\n`);
    break;
  }
  default:
    die(`неизвестная команда: ${cmd} (см. --help)`);
}
